// Command napigo is the napi-go implementation of the benchmark addon (bench/README.md): the same
// functions as the napi-rs and node-addon-api implementations, written the idiomatic way, with
// //napi: annotations and the registrations generated by napi-go gen (zz_napi.go).
package main

//go:generate go run github.com/napi-bindings/napi-go/cmd/napi-go gen -name napigo -js "" -dts ""

import "context"

// Noop does nothing: the cost of a call.
//
//napi:export
func Noop() {}

// Add returns a + b.
//
//napi:export
func Add(a, b float64) float64 { return a + b }

// Echo returns s: a string converted from JS and back.
//
//napi:export
func Echo(s string) string { return s }

// BufferLength returns the length of b, a view of the JS memory (no copy).
//
//napi:export
func BufferLength(b []byte) int { return len(b) }

// MakeBuffer returns a new zero-filled Buffer of n bytes.
//
//napi:export
func MakeBuffer(n int) []byte { return make([]byte, n) }

// ResolveAsync returns a Promise resolved with n by a goroutine.
//
//napi:export
func ResolveAsync(ctx context.Context, n float64) (float64, error) {
	return n, nil
}

// main is required by -buildmode=c-shared; it does not run.
func main() {}
